using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SBCCashier.Web.Models;using SBCCashier.Web.Services;
namespace SBCCashier.Web.Pages.Registrar;
public sealed class IndexModel:PageModel{private readonly CashierStore _store;public IReadOnlyList<RequestRow> Requests{get;private set;}=[];public IReadOnlyList<Student> Students{get;private set;}=[];public string? ErrorMessage{get;private set;}[BindProperty]public RegistrarRequest NewRequest{get;set;}=new();public IndexModel(CashierStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(NewRequest.Fee<0){ErrorMessage="Fee cannot be negative.";Load();return Page();}try{_store.AddRequest(NewRequest);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}public IActionResult OnPostRelease(int id){_store.MarkRequestReleased(id);Load();return Page();}private void Load(){Requests=_store.RegistrarRequests;Students=_store.Students;}}
